message.content:
[
  {
    "sys_fairness_reciprocity": "My life doesn't outrank anyone else's on that island"
  },
  {
    "sys_fairness_reciprocity": "I wouldn't ask another person to do something I'm unwilling to do myself."
  },
  {
    "sys_fairness_reciprocity": "Each of us has exactly the same claim to that boat."
  },
  {
    "sys_fairness_reciprocity": "the closest thing to sharing it evenly is giving everyone an identical chance."
  },
  {
    "sys_fairness_reciprocity": "I'd want us all standing on the same footing, with nobody guilted into it."
  },
  {
    "sys_fairness_reciprocity": "These five people owe me nothing, and I owe them nothing more"
  },
  {
    "sys_fairness_reciprocity": "trade where they give everything and I give nothing back."
  },
  {
    "sys_fairness_reciprocity": "Every person there has the same right to live that I do"
  },
  {
    "sys_fairness_reciprocity": "cutting to the front of a line where everyone's ticket is identical."
  },
  {
    "sys_fairness_reciprocity": "my claim to the boat is no stronger than anyone else's."
  }
]
